import{_ as o,o as t,c as n,a3 as s}from"./chunks/framework.B4L2-OcQ.js";const p=JSON.parse('{"title":"The phone forks a conflicting workout, and the server counts changes","description":"","frontmatter":{"status":"accepted","date":"2026-11-07T00:00:00.000Z"},"headers":[],"relativePath":"docs/adr/0025-the-phone-forks-a-conflicting-workout-and-the-server-counts-changes.md","filePath":"docs/adr/0025-the-phone-forks-a-conflicting-workout-and-the-server-counts-changes.md"}'),r={name:"docs/adr/0025-the-phone-forks-a-conflicting-workout-and-the-server-counts-changes.md"};function a(i,e,h,c,d,l){return t(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="the-phone-forks-a-conflicting-workout-and-the-server-counts-changes" tabindex="-1">The phone forks a conflicting workout, and the server counts changes <a class="header-anchor" href="#the-phone-forks-a-conflicting-workout-and-the-server-counts-changes" aria-label="Permalink to &quot;The phone forks a conflicting workout, and the server counts changes&quot;">​</a></h1><p>ADR 0006 keeps both edits of a workout made on two phones. This ADR settles where the copy is made, what a deletion does against an edit, and what the pull cursor is (<a href="./../accounts#sync">Accounts</a>).</p><ul><li><strong>The phone makes the copy.</strong> The server refuses a push whose workout version doesn&#39;t follow its latest (409 <code>stale-base</code>). The phone pulls, turns its unsent versions into a new workout named after the device, points its own sessions and planned workouts at it, and pushes again. The phone already holds every reference to those versions, so nothing stored on the server is ever rewritten, and the server needs no merge rules beyond &quot;version n + 1 follows n&quot;.</li><li><strong>An edit beats a delete.</strong> A workout deleted on one phone while another pushed a newer version comes back, so a delete never loses someone&#39;s work.</li><li><strong>The cursor is a per-account counter, not a time.</strong> Every row written for an account takes the next number under a lock on the account row. Pulls never skip a row committed late, and the phones&#39; clocks don&#39;t matter. Clocks only decide small last-write-wins fields, where a wrong clock costs little.</li></ul><h2 id="considered-options" tabindex="-1">Considered options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered options&quot;">​</a></h2><ul><li><strong>The server makes the copy</strong>: the phone would learn from the push answer that its version 3 now lives under another id. The server would have to rewrite the sessions and planned workouts in the same push that reference it, and the phone would have to rename its rows to match.</li><li><strong>Delete wins</strong>: simpler, but an edit made on another phone vanishes without a trace.</li><li><strong>A timestamp cursor</strong>: two transactions committing out of order can hide a row from a pull, and phones&#39; clocks drift.</li></ul>',5)])])}const w=o(r,[["render",a]]);export{p as __pageData,w as default};
